+      keys = Array.from({ length: storage.length }, (_, index) => storage.key(index))
+        .filter((key): key is string => (
+          key?.startsWith('zodiacs.') === true || key?.startsWith('zodiacs:') === true
+        ));
+    } catch {
+      ok = false;
+      continue;
+    }
+    for (const key of keys) {
+      try {
+        storage.removeItem(key);
+      } catch {
+        ok = false;
+      }
+    }
+  }
