+    const raw = storage.getItem(LIVING_CHART_GUEST_VAULT_KEY);
+    if (!raw) return null;
+    const parsed = JSON.parse(raw) as { version?: unknown; vaultId?: unknown };
+    return parsed.version === 1 && isAccountV2Id(parsed.vaultId)
